package com.sih.support.security;
import java.util.*; import java.util.stream.*;
import org.springframework.context.annotation.*; import org.springframework.core.convert.converter.Converter; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter; import org.springframework.security.web.SecurityFilterChain;
@Configuration @Profile("secure") public class SecureSecurityConfig {
 @Bean SecurityFilterChain chain(HttpSecurity h)throws Exception{return h.csrf(AbstractHttpConfigurer::disable).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health").permitAll().requestMatchers(HttpMethod.GET,"/api/v1/support/**").hasAnyRole("DIETETICIEN","TECHNICIEN_MAINTENANCE","AGENT_ENTRETIEN","RESPONSABLE_SUPPORT","SUPER_ADMIN").requestMatchers("/api/v1/support/meals/**").hasAnyRole("DIETETICIEN","RESPONSABLE_SUPPORT","SUPER_ADMIN").requestMatchers("/api/v1/support/maintenance/**","/api/v1/support/equipment/**").hasAnyRole("TECHNICIEN_MAINTENANCE","RESPONSABLE_SUPPORT","SUPER_ADMIN").requestMatchers("/api/v1/support/cleaning/**").hasAnyRole("AGENT_ENTRETIEN","RESPONSABLE_SUPPORT","SUPER_ADMIN").anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->j.jwtAuthenticationConverter(converter()))).build();}
 @Bean JwtAuthenticationConverter converter(){JwtAuthenticationConverter c=new JwtAuthenticationConverter();c.setJwtGrantedAuthoritiesConverter(new Roles());return c;} static class Roles implements Converter<Jwt,Collection<GrantedAuthority>>{@Override public Collection<GrantedAuthority>convert(Jwt j){Map<String,Object> a=j.getClaimAsMap("realm_access");if(a==null||!(a.get("roles") instanceof List<?> r))return List.of();return r.stream().map(String::valueOf).map(x->new SimpleGrantedAuthority("ROLE_"+x)).collect(Collectors.toSet());}}
}
